-- Schema fingerprint: run on the live database (SQL editor) and on the replayed baseline; every row must match.
-- Excludes the two report bundle functions (compared separately) and the platform function rls_auto_enable.
select 'columns' k, count(*) n, md5(string_agg(c.relname||'.'||a.attname||format_type(a.atttypid,a.atttypmod)||a.attnotnull||coalesce(pg_get_expr(d.adbin,d.adrelid),''), '|' order by c.relname,a.attnum)) h from pg_class c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where c.relnamespace='public'::regnamespace and c.relkind='r'
union all select 'constraints', count(*), md5(string_agg(c.relname||k.conname||pg_get_constraintdef(k.oid), '|' order by c.relname,k.conname)) from pg_constraint k join pg_class c on c.oid=k.conrelid where k.connamespace='public'::regnamespace
union all select 'indexes', count(*), md5(string_agg(indexdef, '|' order by indexname)) from pg_indexes where schemaname='public'
union all select 'policies', count(*), md5(string_agg(tablename||policyname||cmd||array_to_string(roles,',')||coalesce(qual,'')||coalesce(with_check,''), '|' order by tablename,policyname)) from pg_policies where schemaname='public'
union all select 'triggers', count(*), md5(string_agg(pg_get_triggerdef(t.oid), '|' order by pg_get_triggerdef(t.oid))) from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and c.relnamespace='public'::regnamespace
union all select 'functions', count(*), md5(string_agg(regexp_replace(pg_get_functiondef(p.oid),'\s+',' ','g'), '|' order by p.proname)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='f' and p.proname not in ('rls_auto_enable','create_scout_report_bundle','create_multi_match_scout_report_bundle')
union all select 'rls', count(*), md5(string_agg(relname||relrowsecurity, '|' order by relname)) from pg_class where relnamespace='public'::regnamespace and relkind='r'
union all select 'table_grants', count(*), md5(string_agg(table_name||grantee||privilege_type, '|' order by table_name,grantee,privilege_type)) from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated')
